{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"pygments_lexer":"ipython3","nbconvert_exporter":"python","version":"3.6.4","file_extension":".py","codemirror_mode":{"name":"ipython","version":3},"name":"python","mimetype":"text/x-python"}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code]\n# Santa 2026 dev harness: compiles an embedded C++ solver, runs it on practice + scored puzzles,\n# validates every program, reports per-family stats, writes submission.csv.\nimport base64, csv, json, os, subprocess, sys, time, collections\nfrom concurrent.futures import ThreadPoolExecutor\nfrom pathlib import Path\n\nSOLVER_B64 = \"\"\nCONFIG = json.loads(base64.b64decode(\"\").decode())\n\nt0 = time.time()\ncands = sorted(Path(\"/kaggle/input\").rglob(\"puzzles.csv\"))\nDATA = cands[0].parent\nprint(\"data\", DATA, flush=True)\nwork = Path(\"/kaggle/working\")\nsrc = work / \"solver.cpp\"; binp = work / \"solver\"\nsrc.write_bytes(base64.b64decode(SOLVER_B64))\nr = subprocess.run([\"g++\", \"-std=c++17\", \"-O3\", \"-march=native\", \"-o\", str(binp), str(src)], capture_output=True, text=True)\nif r.returncode:\n    print(r.stderr[:20000]); raise SystemExit(\"compile failed\")\nprint(\"compiled\", round(time.time() - t0, 1), \"s\", flush=True)\n\ndef load(fn):\n    out = []\n    with open(DATA / fn, encoding=\"utf-8\", newline=\"\") as f:\n        for r in csv.DictReader(f):\n            out.append(dict(id=r[\"id\"], starts=json.loads(r[\"starting_values\"]), targets=json.loads(r[\"targets\"]),\n                            limit=int(r[\"value_limit\"]), fam=r.get(\"family\", \"?\") + \"/\" + r.get(\"design_tier\", \"?\")))\n    return out\n\ndef replay(p, cell):\n    if len(cell.encode()) > 131072: raise ValueError(\"cell too big\")\n    prog = json.loads(cell)\n    if len(prog) > 4096: raise ValueError(\"too long\")\n    reg = list(p[\"starts\"]) + [None] * (48 - len(p[\"starts\"]))\n    miss = set(p[\"targets\"]) - set(p[\"starts\"])\n    L = p[\"limit\"]\n    SEEN_V.clear(); SEEN_V.update(p[\"starts\"])\n    for k, ins in enumerate(prog):\n        op, i, j, d = ins\n        if not all(type(x) is int and 0 <= x < 48 for x in (i, j, d)): raise ValueError(f\"{k} bad reg\")\n        a, b = reg[i], reg[j]\n        if a is None or b is None: raise ValueError(f\"{k} undefined\")\n        if op == \"+\": v = a + b\n        elif op == \"-\": v = a - b\n        elif op == \"*\": v = a * b\n        elif op == \"/\" and a % b == 0: v = a // b\n        else: raise ValueError(f\"{k} bad op/div\")\n        if not 1 <= v <= L: raise ValueError(f\"{k} value {v} out of range\")\n        if v in SEEN_V: DUPS[0] += 1\n        SEEN_V.add(v)\n        reg[d] = v; miss.discard(v)\n    if miss: raise ValueError(f\"missing {len(miss)} targets\")\n    return len(prog)\n\ndef run_batch(args, batch):\n    lines = [\" \".join(map(str, (p[\"id\"], p[\"limit\"], len(p[\"starts\"]), len(p[\"targets\"]), *p[\"starts\"], *sorted(p[\"targets\"])))) for p in batch]\n    res = subprocess.run([str(binp), *map(str, args)], input=\"\\n\".join(lines) + \"\\n\", text=True, capture_output=True)\n    if res.returncode:\n        print(\"solver error\", res.stderr[-3000:], flush=True)\n    out = {}\n    for line in res.stderr.splitlines():\n        parts = line.split()\n        if len(parts) == 5 and parts[1] == \"best\":\n            WINS[parts[4]] += 1\n        elif \"error\" in line:\n            ERRS.append(line[:200])\n    for line in res.stdout.splitlines():\n        if line.strip():\n            pid, prog = line.split(\" \", 1)\n            out[pid] = prog\n    return out\n\ndef solve_set(puzzles, args, workers=4, bs=4):\n    batches = [puzzles[i:i + bs] for i in range(0, len(puzzles), bs)]\n    res = {}\n    with ThreadPoolExecutor(workers) as ex:\n        for d in ex.map(lambda b: run_batch(args, b), batches):\n            res.update(d)\n    return res\n\ndef evaluate(puzzles, res, name):\n    fam = collections.defaultdict(lambda: [0, 0, 0])\n    tot = 0; bad = 0\n    counts = {}\n    for p in puzzles:\n        prog = res.get(p[\"id\"])\n        try:\n            n = replay(p, prog)\n        except Exception as e:\n            bad += 1; print(\"INVALID\", p[\"id\"], repr(e)[:200]); continue\n        counts[p[\"id\"]] = n\n        lb = len(set(p[\"targets\"]) - set(p[\"starts\"]))\n        f = fam[p[\"fam\"]]; f[0] += 1; f[1] += n; f[2] += lb\n        tot += n\n    print(f\"== {name}: total {tot} invalid {bad}\")\n    for k, (c, n, lb) in sorted(fam.items()):\n        print(f\"   {k:24s} n={c:4d} instr={n:7d} lb={lb:6d} per_target={n / max(lb, 1):.3f}\")\n    return tot, counts\n\npractice = load(\"practice_puzzles.csv\"); scored = load(\"puzzles.csv\")\nsummary = {}\nWINS = collections.Counter(); ERRS = []; SEEN_V = set(); DUPS = [0]\nfor run in CONFIG[\"runs\"]:\n    args = run[\"args\"]; name = run[\"name\"]\n    t1 = time.time()\n    sets = []\n    if run.get(\"practice\", True): sets.append((\"practice\", practice))\n    if run.get(\"scored\", True): sets.append((\"scored\", scored))\n    for sname, pz in sets:\n        st = run.get(\"start\", 0) if sname == \"scored\" else 0\n        if run.get(\"limit\"): pz = pz[st:st + run[\"limit\"]]\n        elif st: pz = pz[st:]\n        res = solve_set(pz, args, workers=CONFIG.get(\"workers\", 4), bs=CONFIG.get(\"bs\", 4))\n        tot, counts = evaluate(pz, res, f\"{name}/{sname} args={args} ({time.time() - t1:.0f}s)\")\n        print(\"   cfg wins:\", dict(WINS.most_common()), \"errors:\", len(ERRS), ERRS[:3], \"recomputed:\", DUPS[0], flush=True)\n        WINS.clear(); ERRS.clear(); DUPS[0] = 0\n        summary[f\"{name}/{sname}\"] = tot\n        if sname == \"scored\":\n            (work / f\"counts_{name}.json\").write_text(json.dumps(counts))\n            with open(work / f\"sub_{name}.csv\", \"w\", encoding=\"utf-8\", newline=\"\") as f:\n                w = csv.writer(f); w.writerow([\"id\", \"program\"])\n                for p in pz:\n                    if p[\"id\"] in counts: w.writerow([p[\"id\"], res[p[\"id\"]]])\nprint(json.dumps(summary, indent=1))\n(work / \"summary.json\").write_text(json.dumps(summary, indent=1))\n# best-of merge across runs for scored\nbest = {}\nfor run in CONFIG[\"runs\"]:\n    fn = work / f\"sub_{run['name']}.csv\"\n    if not fn.exists(): continue\n    cnt = json.loads((work / f\"counts_{run['name']}.json\").read_text())\n    with open(fn, encoding=\"utf-8\", newline=\"\") as f:\n        for r in csv.DictReader(f):\n            n = cnt[r[\"id\"]]\n            if r[\"id\"] not in best or n < best[r[\"id\"]][0]: best[r[\"id\"]] = (n, r[\"program\"])\nif best:\n    with open(work / \"best_partial.csv\", \"w\", encoding=\"utf-8\", newline=\"\") as f:\n        w = csv.writer(f); w.writerow([\"id\", \"program\"])\n        for p in scored:\n            if p[\"id\"] in best: w.writerow([p[\"id\"], best[p[\"id\"]][1]])\n    tot = sum(v[0] for v in best.values())\n    print(\"MERGED best over runs:\", len(best), \"puzzles, total\", tot)\nprint(\"elapsed\", round(time.time() - t0), \"s\")\n","metadata":{"_uuid":"f2b57722-ba74-48ea-b06c-31b63299733d","_cell_guid":"475bf46e-4937-4e50-bb04-891a96f55635","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}